<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import AppModal from '@/components/AppModal.vue'
import OfficeLogo from '@/components/OfficeLogo.vue'
import AppIcon from '@/components/AppIcon.vue'
import {officineService,accountState,historyLabels,supportPermissionLabels,type OfficeProfile,type Contact,type SupportAssignment,type HistoryEvent} from '@/services/officine'
const route=useRoute();const section=computed(()=>route.path.endsWith('accompagnateurs')?'access':route.path.endsWith('profil')?'profile':'office')
const title=computed(()=>section.value==='access'?'Accompagnateurs':section.value==='profile'?'Mon profil & rôle':'Mon officine')
const loading=ref(false);const busy=ref(false);const error=ref('');const dialogError=ref('');const notice=ref('');const admin=ref(false);const office=ref<OfficeProfile|null>(null);const contacts=ref<Contact[]>([]);const assignments=ref<SupportAssignment[]>([]);const history=ref<HistoryEvent[]>([]);const tab=ref('Informations générales')
const editor=ref(false);const detail=ref(false);const confirm=ref(false);const discard=ref(false);const kind=ref('office');const selected=ref<SupportAssignment|null>(null);const decision=ref('approved');const reason=ref('');const dirtyStart=ref('')
const profileForm=ref<OfficeProfile|null>(null);const accountForm=ref({name:'',phone:'',locale:'fr',profile_version:1});const contactForm=ref<Contact>({id:0,name:'',function:'',email:'',phone:'',type:'professionnel',is_active:true,version:1})
const formSnapshot=()=>JSON.stringify(kind.value==='office'?profileForm.value:kind.value==='account'?accountForm.value:contactForm.value)
async function load(){loading.value=true;error.value='';office.value=null;admin.value=false;contacts.value=[];assignments.value=[];history.value=[];try{
 await officineService.account();if(section.value!=='profile') {const result=await officineService.profile();office.value=result.data;admin.value=result.is_admin;if(admin.value){[contacts.value,assignments.value,history.value]=await Promise.all([officineService.contacts(),officineService.assignments(),officineService.history()])}}
}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
onMounted(load);watch(section,()=>{editor.value=false;detail.value=false;confirm.value=false;notice.value='';load()})
function edit(type:string,c?:Contact){kind.value=type;dialogError.value='';if(type==='office')profileForm.value=JSON.parse(JSON.stringify(office.value));if(type==='account')accountForm.value={name:accountState.user!.name,phone:accountState.user!.phone||'',locale:accountState.user!.locale||'fr',profile_version:accountState.user!.profile_version};if(type==='contact')contactForm.value=c?{...c}:{id:0,name:'',function:'',email:'',phone:'',type:'professionnel',is_active:true,version:1};dirtyStart.value=formSnapshot();editor.value=true}
function closeEditor(){if(busy.value)return;if(dirtyStart.value!==formSnapshot())discard.value=true;else editor.value=false}
async function save(){busy.value=true;dialogError.value='';try{if(kind.value==='office')await officineService.saveProfile(profileForm.value!);else if(kind.value==='account')await officineService.saveAccount(accountForm.value);else {const {id,...data}=contactForm.value;await officineService.saveContact(data,id||undefined)}editor.value=false;notice.value='Modification enregistrée sur le serveur.';await load()}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
function decide(status:string){decision.value=status;reason.value='';dialogError.value='';confirm.value=true}
async function submitDecision(){busy.value=true;dialogError.value='';try{await officineService.decision(selected.value!,decision.value,reason.value);confirm.value=false;detail.value=false;notice.value='Décision enregistrée. Les droits sont revérifiés dès la prochaine requête.';await load()}catch(e){dialogError.value=(e as Error).message}finally{busy.value=false}}
const labels={pending:'À approuver',approved:'Approuvé',refused:'Refusé',revoked:'Retiré',changes_requested:'Modification demandée'}
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 01 · DONNÉES SERVEUR</p><h1>{{title}}</h1><p class="page-subtitle">Officines, identité et accès approuvés.</p></div><button class="button secondary" :disabled="loading||busy" @click="load">Actualiser</button></div><p v-if="error" role="alert" class="alert error">{{error}}</p><p v-if="notice" role="status" class="alert success">{{notice}}</p><p v-if="loading" role="status">Chargement sécurisé de votre espace…</p>
<template v-else-if="!error"><div v-if="section==='profile'&&accountState.user" class="panel"><div class="panel-heading"><div><h2>{{accountState.user.name}}</h2><p class="page-subtitle">{{accountState.user.email}}</p></div><button class="button primary" @click="edit('account')">Modifier mon profil</button></div><div class="form-body"><dl class="application-summary"><dt>Téléphone</dt><dd>{{accountState.user.phone||'Non renseigné'}}</dd><dt>Email vérifié</dt><dd>{{accountState.user.email_verified?'Oui':'Non — vérification nécessaire'}}</dd><dt>Accès</dt><dd>{{accountState.officines.length}} espace(s) autorisé(s) · rôles propres à chaque officine</dd></dl><RouterLink to="/choose-officine" class="button secondary">Choisir une officine</RouterLink><RouterLink v-if="accountState.user.is_support_coordinator" to="/beg/accompagnateurs" class="button secondary">Coordination des accès</RouterLink><RouterLink to="/dashboard/securite" class="button secondary">Sécurité & MFA</RouterLink><p class="module-disclaimer">Pour vérifier ou changer votre email, votre mot de passe et votre MFA, ouvrez l’espace Sécurité.</p></div></div>
<div v-else-if="section==='office'&&office" class="panel"><div class="panel-heading"><div><h2>{{office.name}}</h2><p class="page-subtitle">{{office.slug}} · {{office.status}} · version {{office.profile_version}}</p></div><button v-if="admin" class="button primary" @click="edit('office')">Modifier la fiche</button></div><div class="erp-tabs"><button v-for="t in (admin?['Informations générales','Contacts','Équipe et accès','Accompagnateurs','Historique']:['Informations générales'])" :key="t" :class="{selected:tab===t}" @click="tab=t">{{t}}</button></div><div v-if="tab==='Informations générales'||!admin" class="form-body"><OfficeLogo :version="office.profile_version" :has-logo="office.has_logo" :admin="admin" @saved="load"/><dl class="application-summary"><dt>Pays</dt><dd>{{office.country}}</dd><dt>Département / commune</dt><dd>{{office.department||'À compléter'}} / {{office.city||'À compléter'}}</dd><dt>Adresse</dt><dd>{{office.address||'À compléter'}}</dd><dt>Arrondissement / quartier</dt><dd>{{office.district||'—'}} / {{office.neighborhood||'—'}}</dd><dt>Coordonnées géographiques</dt><dd>{{office.latitude??'—'}} / {{office.longitude??'—'}}</dd><dt>Contact principal</dt><dd>{{office.contact_name||'À compléter'}}</dd><dt>Téléphone</dt><dd>{{office.phone||'À compléter'}}</dd><dt>Email</dt><dd>{{office.email||'Non renseigné'}}</dd></dl><p class="module-disclaimer">Le statut SaaS ne vaut pas autorisation pharmaceutique ou certification ABMed.</p></div>
<div v-else-if="tab==='Contacts'" class="form-body"><div class="section-toolbar"><h3>Contacts de l’officine</h3><button class="button primary" @click="edit('contact')">Ajouter un contact</button></div><p class="module-disclaimer">Un contact n’est pas un compte. La désactivation conserve la fiche et son historique.</p><article v-for="c in contacts" :key="c.id" class="detail-card section-toolbar"><div><strong>{{c.name}} · {{c.function}}</strong><p class="page-subtitle">{{c.email}} · {{c.phone}} · {{c.is_active?'Actif':'Inactif'}}</p></div><button class="button secondary small" @click="edit('contact',c)">Modifier</button></article><p v-if="!contacts.length" class="empty-state">Aucun contact supplémentaire.</p></div>
<div v-else-if="tab==='Équipe et accès'" class="form-body"><h3>Équipe, invitations et rôles</h3><p class="page-subtitle">La liste et les opérations sont limitées à l’officine sélectionnée.</p><RouterLink to="/equipe" class="button primary">Gérer l’équipe et les rôles</RouterLink></div><div v-else-if="tab==='Accompagnateurs'" class="form-body"><p class="page-subtitle">{{assignments.length}} proposition(s) et affectation(s) dans l’historique.</p><RouterLink to="/dashboard/accompagnateurs" class="button primary">Gérer les accompagnateurs</RouterLink></div><div v-else class="form-body"><RouterLink to="/dashboard/journal" class="button secondary">Journal filtrable et détails</RouterLink><ol class="event-list"><li v-for="e in history" :key="e.id"><span class="event-dot"/><div><strong>{{historyLabels[e.action]||e.action}}</strong><small>{{e.created_at}} UTC · événement #{{e.id}}</small></div></li></ol><p v-if="!history.length" class="empty-state">Aucun événement à afficher.</p></div></div>
<div v-else-if="section==='access'&&admin" class="panel"><div class="panel-heading"><div><h2>Accès des accompagnateurs</h2><p class="page-subtitle">{{office?.name}} · chaque approbation est explicite.</p></div></div><div class="table-scroll"><table><thead><tr><th>ACCOMPAGNATEUR</th><th>PÉRIMÈTRE</th><th>PÉRIODE</th><th>ÉTAT</th><th>ACTION</th></tr></thead><tbody><tr v-for="a in assignments" :key="a.id"><td><strong>{{a.name}}</strong><span class="table-subtitle">Proposition #{{a.id}} · v{{a.version}}</span></td><td>{{a.scope}}</td><td>{{a.starts_on}} → {{a.ends_on}}</td><td><span class="status-badge" :class="a.status">{{a.expired?'Proposition expirée':labels[a.status]}}</span></td><td><button class="button secondary small" @click="selected=a;detail=true">Ouvrir</button></td></tr><tr v-if="!assignments.length"><td colspan="5" class="empty-state">Aucun accompagnateur proposé. Les propositions viennent de la coordination.</td></tr></tbody></table></div><div class="panel-foot">Les accès expirés, refusés ou retirés ne donnent aucun droit. L’API revérifie chaque requête.</div></div><div v-else class="panel form-body"><h2>Administration requise</h2><p>Seuls les administrateurs actifs de l’officine peuvent gérer ses accompagnateurs.</p></div></template>
<AppModal :model-value="editor" :title="kind==='office'?'Modifier la fiche officine':kind==='account'?'Modifier mon profil':'Contact de l’officine'" :busy="busy" size="wide" @update:model-value="closeEditor"><form id="api-office-form" class="form-body form-grid" @submit.prevent="save"><p v-if="dialogError" class="alert error span-2" role="alert">{{dialogError}}</p><template v-if="kind==='office'&&profileForm"><label>Nom<input v-model="profileForm.name" required maxlength="150"/></label><label>Contact principal<input v-model="profileForm.contact_name" required maxlength="150"/></label><label>Pays<input v-model="profileForm.country" required maxlength="80"/></label><label>Département<input v-model="profileForm.department" required maxlength="120"/></label><label>Commune<input v-model="profileForm.city" required maxlength="120"/></label><label>Téléphone<input v-model="profileForm.phone" required maxlength="40"/></label><label>Email<input v-model="profileForm.email" type="email" maxlength="254"/></label><label>Arrondissement<input v-model="profileForm.district" maxlength="120"/></label><label>Quartier<input v-model="profileForm.neighborhood" maxlength="120"/></label><label>Latitude<input v-model="profileForm.latitude" type="number" step="any" min="-90" max="90"/></label><label>Longitude<input v-model="profileForm.longitude" type="number" step="any" min="-180" max="180"/></label><label class="span-2">Adresse descriptive<textarea v-model="profileForm.address" required maxlength="500" rows="3"/></label></template><template v-else-if="kind==='account'"><label>Nom<input v-model="accountForm.name" required maxlength="150"/></label><label>Téléphone<input v-model="accountForm.phone" maxlength="40"/></label><label>Langue de préférence<select v-model="accountForm.locale"><option value="fr">Français</option><option value="en">Anglais</option></select></label><p class="module-disclaimer">Préférence enregistrée ; l’interface actuelle reste en français.</p></template><template v-else><label>Nom<input v-model="contactForm.name" required maxlength="150"/></label><label>Fonction<input v-model="contactForm.function" required maxlength="120"/></label><label>Téléphone<input v-model="contactForm.phone" maxlength="40"/></label><label>Email<input v-model="contactForm.email" type="email" maxlength="254"/></label><label>Type<select v-model="contactForm.type"><option value="professionnel">Professionnel</option><option value="urgence">Urgence</option><option value="autre">Autre</option></select></label><label>État<select v-model="contactForm.is_active"><option :value="true">Actif</option><option :value="false">Inactif</option></select></label></template></form><template #footer><button :disabled="busy" class="button secondary" @click="closeEditor">Annuler</button><button class="button primary" :disabled="busy" form="api-office-form" type="submit">{{busy?'Enregistrement…':'Enregistrer'}}</button></template></AppModal>
<AppModal v-model="discard" title="Abandonner les modifications ?" size="small"><div class="form-body"><p>Les changements non enregistrés seront perdus.</p></div><template #footer><button class="button secondary" @click="discard=false">Continuer la saisie</button><button class="button danger" @click="discard=false;editor=false">Abandonner</button></template></AppModal>
<AppModal v-model="detail" title="Accès de l’accompagnateur"><div v-if="selected" class="form-body"><dl class="application-summary"><dt>Nom</dt><dd>{{selected.name}}</dd><dt>Périmètre</dt><dd>{{selected.scope}}</dd><dt>Période</dt><dd>{{selected.starts_on}} → {{selected.ends_on}}</dd><dt>Permissions</dt><dd><ul><li v-for="p in selected.permissions" :key="p">{{supportPermissionLabels[p]||p}}</li></ul></dd><dt>État</dt><dd>{{labels[selected.status]}}</dd><dt>Motif</dt><dd>{{selected.decision_reason||'Aucun'}}</dd></dl><p class="module-disclaimer">L’accord ne donne jamais accès à l’équipe, aux invitations ou à l’administration. Tout changement de portée ou période exige une nouvelle proposition et approbation.</p></div><template #footer><button class="button secondary" @click="detail=false">Fermer</button><template v-if="selected?.status==='pending'&&!selected.expired"><button class="button secondary" @click="decide('changes_requested')">Demander une modification</button><button class="button secondary" @click="decide('refused')">Refuser</button><button class="button primary" @click="decide('approved')">Approuver l’accès</button></template><button v-if="selected?.status==='approved'" class="button danger" @click="decide('revoked')">Retirer l’accès</button></template></AppModal>
<AppModal v-model="confirm" :title="decision==='approved'?'Approuver cet accès ?':decision==='refused'?'Refuser cet accès ?':decision==='changes_requested'?'Demander une modification ?':'Retirer cet accès ?'" :busy="busy" size="small"><form id="api-access-decision" class="form-body" @submit.prevent="submitDecision"><p v-if="dialogError" class="alert error" role="alert">{{dialogError}}</p><p>{{selected?.name}} · {{selected?.scope}}</p><label v-if="decision!=='approved'">Motif<textarea v-model="reason" required maxlength="2000" rows="3"/></label><p v-else>L’accès sera limité aux permissions et à la période affichées.</p></form><template #footer><button class="button secondary" :disabled="busy" @click="confirm=false">Annuler</button><button class="button primary" :disabled="busy" form="api-access-decision" type="submit">Confirmer</button></template></AppModal></section></template>
